/**
 *
 */
export function getCountryList() {
	return list.slice().sort((a, b) => a.label < b.label ? -1 : 1)
}

/**
 * @param code The country code to look up
 */
export function getNameForCountryCode(code: string): string {
	const element = list.find((e) => e.code === code)
	if (element) {
		return element.label
	}

	return ''
}
